scripts.script:
local replicated_storage = game:GetService("ReplicatedStorage");
local workspace = game:GetService("Workspace");
local players = game:GetService("Players");

local local_player = players.LocalPlayer;
local camera = workspace.CurrentCamera;

local events = replicated_storage.Events;

getgenv().we_ud = not getgenv().we_ud;

if (getgenv().we_ud) then
    repeat
        events.Chat:FireServer("\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n Chat is broken due to an unknown bug, sorry!");
        local tool = camera:FindFirstChild("Arms") and camera.Arms:FindFirstChildWhichIsA("Model");

        if (tool) then
            for _, player in (players:GetPlayers()) do
                if (player == local_player) then
                    continue;
                end
                if (player.Team == local_player.Team) then
                    continue;
                end
                local character = player.Character;
                if (not character) or (character:GetAttribute("SpawnProtection")) then
                    continue;
                end
                local humanoid = character:FindFirstChild("Humanoid");
                local head = character:FindFirstChild("Head");
                if (not head) or (not humanoid) or (humanoid.Health <= 0) then
                    continue;
                end
                events.Shoot:FireServer(
                    {
                        {
                            "BulletHit",
                            {
                                {
                                    HitPlr = player;
                                    HitPart = head;
                                    Extras = {
                                        Equipment = false,
                                        HitNorm = Vector3.new(Vector3.zero);
                                        Melee = true;
                                        Origin = head.Position
                                    };
                                    Damage = humanoid.Health;
                                    Type = "Equipment";
                                    Melee = false;
                                    Aiming = {
                                        true;
                                        true
                                    };
                                    NumberCol = 0;
                                    StartPos = head.Position;
                                    HitPos = head.Position;
                                    HitHuman = humanoid;
                                    AblazeChance = 0;
                                    Killed = true;
                                    PlayerPos = head.Position;
                                    DidWallb = true;
                                    DidRico = true;
                                    ClientHRPPos = head.Position;
                                    Weapon = tool.Name;
                                }
                            };
                            {
                                Aiming = true;
                                QuickAimed = true;
                                Equipped = "Melee";
                                Pos = head.Position;
                            }
                        }
                    }
                );
            end
        end
        task.wait();
    until (not getgenv().we_ud);
end

local eventbypass

eventbypass = hookmetamethod(game, "__namecall", function(self, ...)
    local method = getnamecallmethod()
    local args = {...}

    if not checkcaller() and self.Name == "Reliable" and method == "FireServer" and args[1]["\f"][1][1] == true then
        return 
    end
    return eventbypass(self, ...)
end)

while task.wait() do
local args = {
	workspace:WaitForChild("Balls"):WaitForChild("InazumaBall")
}
game:GetService("ReplicatedStorage"):WaitForChild("Events"):WaitForChild("AttachBall"):FireServer(unpack(args))

end

game:GetService("ReplicatedStorage").Packages._Index["sleitnick_knit@1.5.1"].knit.Services.RandomPotionService.RE.BuyPotionEvent:FireServer(table.unpack({
    [1] = -9e60,
    [2] = {
    },
    [3] = true,
    [4] = "hax",
}))
